  constructor(
    public language: SiteLanguageService,
    private router: Router,
    private host: ElementRef<HTMLElement>,
    private menuCtrl: MenuController
  ) {}

  async toggleAppMenu(): Promise<void> {
    await this.menuCtrl.toggle();
  }

  get isStore(): boolean { return this.mode === 'store'; }
  get loggedIn(): boolean { return GAccount.IsLoggedIn(); }
  get cartCount(): number { return this.courseCount + this.productCount; }
  get coursesDisabled(): boolean { return G.IsCourseDisabled; }
  get productsDisabled(): boolean { return G.IsProductDisabled; }
  get catalogDisabled(): boolean { return this.isStore ? this.productsDisabled : this.coursesDisabled; }
  get catalogPath(): string { return this.isStore ? '/Product/Search' : '/Home/Search'; }
  get pageKey(): string { return this.isStore ? 'learn.store.' : 'learn.home.'; }

  ngOnInit(): void {
    this.activeTab = this.isStore ? 'products' : 'courses';
    this.subscriptions.add(GResponse.getCartCoursesCount().subscribe(count => this.courseCount = count));
    this.subscriptions.add(GResponse.getCartProductsCount().subscribe(count => this.productCount = count));
  }

  setTab(tab: 'courses' | 'products'): void {
    this.activeTab = tab;
  }

  url(path: string): string { return this.language.url(path); }
  gradeLabel(grade: number): string { return this.language.text('learn.grade.' + grade); }

  search(): void {
    if (this.catalogDisabled) { return; }
    void this.router.navigate([this.url(this.catalogPath)], {
      queryParams: { title: this.query.trim(), page: 1 }
    });
  }

  topicQuery(id: string): { title: string; page: number } {
    const namespace = this.isStore ? 'learn.collection.' : 'learn.subject.';
    const title = this.language.text(namespace + id + '.search');
    return { title: title.trim(), page: 1 };
  }

  selectGrade(grade: number): void {
    if (grade === 1) {
      this.selectedGrade = 1;
      this.comingSoonGrade = null;
    } else {
      this.comingSoonGrade = grade;
    }
  }

  dismissComingSoon(): void {
    this.comingSoonGrade = null;
  }

  openSampleModal(): void {
    this.sampleModalOpen = true;
  }

  closeSampleModal(): void {
    this.sampleModalOpen = false;
  }

  goToDirectSearch(searchQuery: string): void {
    if (this.catalogDisabled) { return; }
    void this.router.navigate([this.url(this.catalogPath)], {
      queryParams: { title: searchQuery.trim(), page: 1 }
    });
  }

  goToSubject(categoryId: number): void {
    if (this.catalogDisabled) { return; }
    void this.router.navigate([this.url(this.catalogPath)], {
      queryParams: { categoryIds: String(categoryId), page: 1 }
    });
  }

  async scrollTo(id: string): Promise<void> {
    const target = this.host.nativeElement.querySelector<HTMLElement>('#' + id);
    if (!target || !this.content) { return; }
    const scroller = await this.content.getScrollElement();
    const top = target.getBoundingClientRect().top - scroller.getBoundingClientRect().top + scroller.scrollTop - 24;
    await this.content.scrollToPoint(0, top, window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 450);
  }

  leave(): void {
    this.menuOpen = false;
    this.searchOpen = false;
    this.sampleModalOpen = false;
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
